import requests
from abc import ABC, abstractmethod
from urllib.robotparser import RobotFileParser

class BaseCrawler(ABC):
    def __init__(self, base_url):
        self.base_url = base_url
        self.robot_parser = RobotFileParser()
        self.robot_parser.set_url(f"{base_url}/robots.txt")
        self.robot_parser.read()

    def is_allowed(self, path):
        return self.robot_parser.can_fetch("*", f"{self.base_url}{path}")

    @abstractmethod
    def discover_documents(self):
        pass

    def fetch_page(self, path):
        if not self.is_allowed(path):
            raise PermissionError(f"robots.txt disallows {path}")
        response = requests.get(f"{self.base_url}{path}")
        response.raise_for_status()
        return response.text


# ai_orchestrator/source_seeding/crawlers/parliament_crawler.py
from .base_crawler import BaseCrawler
from bs4 import BeautifulSoup

class ParliamentCrawler(BaseCrawler):
    def discover_documents(self):
        documents = []
        html = self.fetch_page("/bills")
        soup = BeautifulSoup(html, "html.parser")
        
        for item in soup.select(".bill-list-item a"):
            doc_url = item["href"]
            doc_type = "bill"
            title = item.text.strip()
            documents.append({
                "source_url": f"{self.base_url}{doc_url}",
                "document_type": doc_type,
                "title": title
            })
        return documents


