from abc import ABC, abstractmethod
import hashlib

class BaseParser(ABC):
    @abstractmethod
    def parse(self, content, metadata):
        pass

    def calculate_checksum(self, content):
        return hashlib.sha256(content.encode()).hexdigest()


# ai_orchestrator/source_seeding/parsers/parliament_parser.py
from .base_parser import BaseParser
from bs4 import BeautifulSoup

class ParliamentParser(BaseParser):
    def parse(self, html_content, metadata):
        soup = BeautifulSoup(html_content, "html.parser")
        
        # Extract date from page
        date_element = soup.select_one(".bill-date")
        date_published = date_element.text.strip() if date_element else None
        
        # Extract jurisdiction
        jurisdiction = "Ghana Parliament"
        
        # Add to metadata
        metadata.update({
            "date_published": date_published,
            "jurisdiction": jurisdiction,
            "file_type": "html",
            "checksum": self.calculate_checksum(html_content)
        })
        return metadata


# ai_orchestrator/source_seeding/storage/document_storage.py
import uuid
import os
from datetime import datetime

class DocumentStorage:
    def __init__(self, storage_path="./documents"):
        self.storage_path = storage_path
        os.makedirs(storage_path, exist_ok=True)
        
    def save_document(self, content, metadata):
        doc_id = str(uuid.uuid4())
        file_type = metadata.get("file_type", "txt")
        file_path = os.path.join(self.storage_path, f"{doc_id}.{file_type}")
        
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(content)
            
        # In production, this would be a database insert
        return {
            "id": doc_id,
            "file_path": file_path,
            "metadata": metadata,
            "created_at": datetime.now().isoformat()
        }


# ai_orchestrator/source_seeding/tasks/celery_tasks.py
from celery import Celery
from .crawlers.parliament_crawler import ParliamentCrawler
from .parsers.parliament_parser import ParliamentParser
from .storage.document_storage import DocumentStorage

app = Celery("source_seeding", broker="redis://localhost:6379/0")

@app.task
def seed_parliament_documents():
    crawler = ParliamentCrawler("https://parliament.gh")
    documents = crawler.discover_documents()
    
    parser = ParliamentParser()
    storage = DocumentStorage()
    
    results = []
    for doc in documents:
        content = requests.get(doc["source_url"]).text
        metadata = parser.parse(content, doc)
        stored = storage.save_document(content, metadata)
        results.append(stored)
    
    return {"status": "completed", "count": len(results)}


