import pytest
from ai_orchestrator.source_seeding.crawlers.parliament_crawler import ParliamentCrawler
from unittest.mock import Mock, patch

def test_parliament_crawler_discovery():
    mock_html = """
    <div class="bill-list-item">
        <a href="/bills/2023/bill1" class="bill-link">Test Bill 1</a>
    </div>
    <div class="bill-list-item">
        <a href="/bills/2023/bill2" class="bill-link">Test Bill 2</a>
    </div>
    """
    
    with patch.object(ParliamentCrawler, "fetch_page", return_value=mock_html):
        crawler = ParliamentCrawler("https://parliament.gh")
        documents = crawler.discover_documents()
        
        assert len(documents) == 2
        assert documents[0]["title"] == "Test Bill 1"
        assert documents[0]["source_url"] == "https://parliament.gh/bills/2023/bill1"


